Here's a complete example of data-driven MSTest tests for your `PriceCalculator`:

```csharp
using Microsoft.VisualStudio.TestTools.UnitTesting;

[TestClass]
public class PriceCalculatorTests
{
    private PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new PriceCalculator();

    // --- DataRow: inline test cases for CalculateTotal ---
    [TestMethod]
    [DataRow(10.0, 1, 10.0)]
    [DataRow(10.0, 3, 30.0)]
    [DataRow(0.0, 5, 0.0)]
    [DataRow(19.99, 2, 39.98)]
    [DataRow(100.0, 0, 0.0)]
    public void CalculateTotal_WithDataRow_ReturnsExpected(
        double price, int quantity, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)price, quantity);
        Assert.AreEqual((decimal)expected, result);
    }

    // --- DataRow: inline test cases for ApplyDiscount ---
    [TestMethod]
    [DataRow(100.0, 10.0, 90.0)]
    [DataRow(100.0, 0.0, 100.0)]
    [DataRow(100.0, 100.0, 0.0)]
    [DataRow(49.99, 50.0, 24.995)]
    [DataRow(200.0, 25.0, 150.0)]
    public void ApplyDiscount_WithDataRow_ReturnsExpected(
        double total, double discountPercent, double expected)
    {
        var result = _calculator.ApplyDiscount((decimal)total, (decimal)discountPercent);
        Assert.AreEqual((decimal)expected, result);
    }

    // --- DynamicData from method: complex/edge-case scenarios ---
    [TestMethod]
    [DynamicData(nameof(GetDiscountEdgeCases), DynamicDataSourceType.Method)]
    public void ApplyDiscount_EdgeCases_ReturnsExpected(
        decimal total, decimal discountPercent, decimal expected)
    {
        var result = _calculator.ApplyDiscount(total, discountPercent);
        Assert.AreEqual(expected, result);
    }

    private static IEnumerable<object[]> GetDiscountEdgeCases()
    {
        yield return new object[] { 0.01m, 50m, 0.005m };
        yield return new object[] { 999999.99m, 15m, 849999.9915m };
        yield return new object[] { 0m, 10m, 0m };
    }

    // --- DynamicData from property: CalculateTotal scenarios ---
    [TestMethod]
    [DynamicData(nameof(TotalTestCases), DynamicDataSourceType.Property)]
    public void CalculateTotal_DynamicData_ReturnsExpected(
        decimal price, int quantity, decimal expected)
    {
        var result = _calculator.CalculateTotal(price, quantity);
        Assert.AreEqual(expected, result);
    }

    public static IEnumerable<object[]> TotalTestCases => new[]
    {
        new object[] { 5.50m, 4, 22.00m },
        new object[] { 0.01m, 100, 1.00m },
        new object[] { 1000m, 1, 1000m },
    };

    // --- Validate invalid inputs throw ---
    [TestMethod]
    [DataRow(-1.0, 1)]
    [DataRow(10.0, -1)]
    public void CalculateTotal_InvalidInputs_Throws(double price, int quantity)
    {
        Assert.ThrowsException<ArgumentException>(
            () => _calculator.CalculateTotal((decimal)price, quantity));
    }

    [TestMethod]
    [DataRow(100.0, -5.0)]
    [DataRow(100.0, 101.0)]
    public void ApplyDiscount_InvalidPercent_Throws(double total, double discount)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount((decimal)total, (decimal)discount));
    }
}
```

**Key patterns used:**

| Technique | Best for |
|-----------|----------|
| `[DataRow]` | Simple inline values (only compile-time constants — no `decimal` literals) |
| `[DynamicData]` method | Complex types, `decimal`, computed values |
| `[DynamicData]` property | Reusable datasets shared across tests |

**Notes:**
- `DataRow` only supports primitive constants, so use `double` there and cast to `decimal` in the method body.
- `DynamicData` supports `decimal` directly since values aren't compile-time attributes.
- `[TestInitialize]` keeps each test isolated with a fresh instance.
